const initial = { busy: false, error: null };
const reduce = (s, e) => e.type === 'submit' ? { ...s, busy: true }
                    : e.type === 'failed' ? { ...s, busy: false, error: e.reason }
                    : s;
const events$ = new Subject();
const state$ = events$.pipe(
  scan(reduce, initial),
  startWith(initial),
  shareReplay(1)          // replay the current state to late subscribers
);
const dispatch = (e) => events$.next(e);
